diff --git a/repro-18575/repro.cjs b/repro-18575/repro.cjs
new file mode 100644
index 0000000..5aba480
--- /dev/null
+++ b/repro-18575/repro.cjs
@@ -0,0 +1,52 @@
+"use strict";
+
+// Run with: node -r ./repro-18575/win32-sim.cjs repro-18575/repro.cjs
+const assert = require("node:assert");
+const path = require("node:path");
+const { Linter, ESLint } = require("..");
+
+const code = "foo();";
+const rules = { "no-undef": "error" };
+
+assert.strictEqual(path, path.win32, "preload not active");
+console.log(`simulated platform=${process.platform} cwd=${process.cwd()}`);
+
+const cases = [
+    { file: "C:\\Project\\foo.js", expectIgnored: false, note: "inside cwd (control)" },
+    { file: "C:\\other\\foo.js", expectIgnored: true, note: "same drive, outside cwd (control)" },
+    { file: "F:\\foo.js", expectIgnored: true, note: "different drive (reported)" }
+];
+
+(async () => {
+    let failures = 0;
+
+    for (const { file, expectIgnored, note } of cases) {
+        console.log(`\n== ${file}  [${note}]  path.relative(cwd, file) = ${JSON.stringify(path.relative(process.cwd(), file))}`);
+
+        // Linter (reporter's snippet)
+        const linter = new Linter({ configType: "flat" });
+        const msgs = linter.verify(code, { rules }, file);
+        const linterIgnored = msgs.length === 1 && /^No matching configuration found/u.test(msgs[0].message);
+
+        console.log(`Linter#verify: ${msgs.map(m => `${m.ruleId}: ${m.message}`).join(" | ")}`);
+
+        // ESLint API, same as `eslint --no-config-lookup --rule "no-undef: error" --stdin --stdin-filename <file>`
+        const eslint = new ESLint({ overrideConfigFile: true, overrideConfig: { rules } });
+        const [result] = await eslint.lintText(code, { filePath: file, warnIgnored: true });
+        const eslintIgnored = result.messages.length === 1 && /^File ignored/u.test(result.messages[0].message);
+        const isIgnored = await eslint.isPathIgnored(file);
+
+        console.log(`ESLint#lintText: ${result.messages.map(m => `${m.ruleId}: ${m.message}`).join(" | ")}`);
+        console.log(`ESLint#isPathIgnored: ${isIgnored}`);
+
+        for (const [what, actual] of [["Linter#verify", linterIgnored], ["ESLint#lintText", eslintIgnored], ["ESLint#isPathIgnored", isIgnored]]) {
+            if (actual !== expectIgnored) {
+                failures++;
+                console.log(`  BUG: ${what} expected ${expectIgnored ? "ignored" : "linted"}, got ${actual ? "ignored" : "linted"}`);
+            }
+        }
+    }
+
+    console.log(failures ? `\n${failures} mismatch(es): bug reproduced` : "\nall cases behave as expected");
+    process.exitCode = failures ? 1 : 0;
+})();
diff --git a/repro-18575/win32-sim.cjs b/repro-18575/win32-sim.cjs
new file mode 100644
index 0000000..cc5dd82
--- /dev/null
+++ b/repro-18575/win32-sim.cjs
@@ -0,0 +1,21 @@
+"use strict";
+
+/*
+ * Preload (`node -r`) that simulates Windows path semantics on a non-Windows host:
+ * every `require("path")` / `require("node:path")` gets `path.win32`,
+ * `process.platform` is "win32" and `process.cwd()` is a directory on drive C:.
+ */
+const Module = require("node:module");
+const path = require("node:path");
+
+const SIM_CWD = process.env.SIM_CWD || "C:\\Project";
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return path.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+Object.defineProperty(process, "platform", { value: "win32" });
+process.cwd = () => SIM_CWD;
